-- Rifts World Book 23: Xiticix Invasion - its gear. Fifteen new rows from the
-- Xiticix Weapons chapter (printed 77-82): nine resin melee weapons, the Resin
-- Claws and Shoulder Spikes, and the four ranged weapons a Queen makes.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-xiticix-invasion-gear.sql
--
-- ALL 15 ARE NEW - catalog-diff --table gear --remote, 2026-10-01. The one
-- near name, Resin Spike, is Wormwood's and a different item.
--
-- EVERY NAME CARRIES "Xiticix", including the six the book heads without it
-- (Resin Claws, Resin Shoulder Spikes, Resin Spike Gun, Shooting Shoulder
-- Spikes, Resin Spitter, TK-Rifle), so they sort together and none collides
-- with another book's TK weapon.
--
-- A RANGE IS STORED BY ITS LOW END. cost and weight_lbs hold the low figure of
-- the printed range; cost_note and the description give the whole range.
--
-- PRINTED 81-82 SET TWO ENTRIES SIDE BY SIDE and the text layer interleaves
-- them. The Spike Gun and the Shooting Shoulder Spikes were read off 150 dpi
-- renders. The Spike Gun's upper price is printed short a digit, and the
-- TK-Rifle's rate of fire repeats the Spike Gun's wording; both rows say so.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('xiticix-bayonet', 'Xiticix Bayonet or Hand-Held Knife', 'rifts', 'weapon', 3, 3000, '3,000-5,000 credits; uncommon.', '1D4 M.D. plus Supernatural P.S. punch damage', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A narrow double-edged resin blade for stabbing and slashing. Standard on the Xiticix TK-Rifle, and sometimes fixed to a fighter''s body as an extra spike. Weighs 3-4 lbs. Made of Xiticix Mega-Damage resin; a wielder needs a P.S. of 21 or higher, and a weaker one strikes and parries without attribute or skill bonuses. A character who does not have Supernatural P.S. does the weapon damage alone.', 'Rifts World Book 23: Xiticix Invasion p.77'),
('xiticix-double-dagger', 'Xiticix Double-Dagger', 'rifts', 'weapon', 6, 10000, '10,000-15,000 credits; very rare.', '2D4+2 M.D. plus Supernatural P.S. punch damage', 1, 'Melee; thrown 50 ft without bonuses, -1 to strike per additional 10 ft', NULL, NULL, NULL, NULL, NULL, 'A central grip with a long curved blade at each end, favored by Super-Warriors and Leapers. +1 to strike and +2 to parry in hand to hand, not when thrown. Leapers coat it with their poison (1D4x100 S.D.C./Hit Points to humans and most D-Bees, or 4D6 M.D. plus 1D6 M.D. at the start of each melee round for 1D6 melees); a coating takes one melee action, lasts two cutting attacks and needs exposed flesh. Weighs 6-7 lbs. Made of Xiticix Mega-Damage resin; a wielder needs a P.S. of 21 or higher, and a weaker one strikes and parries without attribute or skill bonuses. A character who does not have Supernatural P.S. does the weapon damage alone.', 'Rifts World Book 23: Xiticix Invasion p.78'),
('xiticix-hooked-short-sword', 'Xiticix Hooked Short Sword', 'rifts', 'weapon', 8, 8000, '8,000-12,000 credits; uncommon.', '1D6 M.D. plus Supernatural P.S. punch damage', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A hooked, serrated short sword for fighting, parrying and disarming; the serrated edge saws through M.D.C. cable, chain and supports. +1 to strike, +2 to parry, +3 to disarm. Weighs 8-10 lbs. Made of Xiticix Mega-Damage resin; a wielder needs a P.S. of 21 or higher, and a weaker one strikes and parries without attribute or skill bonuses. A character who does not have Supernatural P.S. does the weapon damage alone.', 'Rifts World Book 23: Xiticix Invasion p.78'),
('xiticix-mace', 'Xiticix Mace or Morning Star', 'rifts', 'weapon', 14, 11000, '11,000-15,000 credits; rare.', '1D6+4 M.D. plus Supernatural P.S. punch damage', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A large club ending in a spiked ball, used one- or two-handed. +1 to parry and +1 to disarm. Weighs 14-18 lbs. Made of Xiticix Mega-Damage resin; a wielder needs a P.S. of 21 or higher, and a weaker one strikes and parries without attribute or skill bonuses. A character who does not have Supernatural P.S. does the weapon damage alone.', 'Rifts World Book 23: Xiticix Invasion p.78'),
('xiticix-long-sword', 'Xiticix Long Sword', 'rifts', 'weapon', 12, 12000, '12,000-15,000 credits; uncommon.', '2D6 M.D. plus Supernatural P.S. punch damage', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A large resin sword used one- or two-handed. +1 to parry and +1 to disarm. Weighs 12-15 lbs. Made of Xiticix Mega-Damage resin; a wielder needs a P.S. of 21 or higher, and a weaker one strikes and parries without attribute or skill bonuses. A character who does not have Supernatural P.S. does the weapon damage alone.', 'Rifts World Book 23: Xiticix Invasion p.79'),
('xiticix-spear', 'Xiticix Spear', 'rifts', 'weapon', 10, 7000, '7,000-10,000 credits; uncommon.', '1D6+3 M.D. stabbing, slashing or thrown, or 1D4 M.D. with the blunt end, each plus Supernatural P.S. punch damage', 1, 'Melee; thrown 300 ft by a Xiticix, 120 ft by a bionic or robot P.S. of 21 or higher, about 60 ft by most humans and D-Bees', NULL, NULL, NULL, NULL, NULL, 'A favorite of Xiticix Warriors, used one- or two-handed to stab, parry, strike with the blunt end or throw. +1 to disarm, +2 to parry, +3 to strike when thrown. Weighs 10-12 lbs. Made of Xiticix Mega-Damage resin; a wielder needs a P.S. of 21 or higher, and a weaker one strikes and parries without attribute or skill bonuses. A character who does not have Supernatural P.S. does the weapon damage alone.', 'Rifts World Book 23: Xiticix Invasion p.79'),
('xiticix-spike-whip', 'Xiticix Spike Whip', 'rifts', 'weapon', 12, 10000, '10,000-14,000 credits; rare.', '1D6+4 M.D. plus Supernatural P.S. punch damage', 1, 'Melee, with a 5-6 ft reach', NULL, NULL, NULL, NULL, NULL, 'A spiked resin ball on a length of cord, used like a ball and chain; the handle carries a small spike for stabbing and parrying. +1 to strike, +3 to disarm, +2 to entangle, only with W.P. Ball and Chain or W.P. Whip. Cannot be thrown well. Weighs 12-15 lbs. Made of Xiticix Mega-Damage resin; a wielder needs a P.S. of 21 or higher, and a weaker one strikes and parries without attribute or skill bonuses. A character who does not have Supernatural P.S. does the weapon damage alone.', 'Rifts World Book 23: Xiticix Invasion p.79'),
('xiticix-beheading-axe', 'Xiticix Beheading Axe', 'rifts', 'weapon', 15, 15000, '15,000-18,000 credits; rare.', '2D6+6 M.D. two-handed, or 1D6+3 M.D. one-handed, each plus Supernatural P.S. punch damage', 1, 'Melee; thrown 20 ft at -6 to strike with no bonuses, -2 per additional 10 ft', NULL, NULL, NULL, NULL, NULL, 'A large two-handed axe favored by Warriors and Super-Warriors. +3 to strike and +1 to parry, two-handed only. Weighs 15-20 lbs. Made of Xiticix Mega-Damage resin; a wielder needs a P.S. of 21 or higher, and a weaker one strikes and parries without attribute or skill bonuses. A character who does not have Supernatural P.S. does the weapon damage alone.', 'Rifts World Book 23: Xiticix Invasion p.80'),
('xiticix-sickle-axe', 'Xiticix Sickle Axe', 'rifts', 'weapon', 10, 12000, '12,000-15,000 credits; uncommon.', '1D6+4 M.D. plus Supernatural P.S. punch damage', 1, 'Melee; thrown 50 ft, -1 to strike per additional 10 ft', NULL, NULL, NULL, NULL, NULL, 'An axe blade backed by a narrow curved pick; a weapon for fighters and a digging tool for Workers. +2 to strike and +1 to parry; +1 to strike when thrown. The range line says it is thrown without bonuses and the bonus line gives a thrown bonus; both are stored as printed. Weighs 10-12 lbs. Made of Xiticix Mega-Damage resin; a wielder needs a P.S. of 21 or higher, and a weaker one strikes and parries without attribute or skill bonuses. A character who does not have Supernatural P.S. does the weapon damage alone.', 'Rifts World Book 23: Xiticix Invasion p.80'),
('xiticix-resin-claws', 'Xiticix Resin Claws', 'rifts', 'weapon', 8, NULL, 'Available only to Xiticix.', '1D6 M.D. plus Supernatural P.S. punch damage', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A three-bladed resin claw bonded to the hand of a fighting-class Xiticix; similar spikes and blades may go on the forearm, elbows, shoulders and knees. +1 to parry and +1 to disarm. Made and applied by a Digger or a Queen. Weighs 8-10 lbs.', 'Rifts World Book 23: Xiticix Invasion p.81'),
('xiticix-resin-shoulder-spikes', 'Xiticix Resin Shoulder Spikes', 'rifts', 'armor', 10, NULL, 'Available only to Xiticix.', '+1D6 M.D. to shoulder blocks and ram attacks', 1, NULL, NULL, NULL, NULL, NULL, 15, 'Resin plating for the shoulder of a fighting-class Xiticix, most common on Warriors and Leapers. Adds 15 M.D.C. to the arm, and must be destroyed before the upper arm can be severed. Made and applied by a Digger or a Queen. Weighs 10-12 lbs.', 'Rifts World Book 23: Xiticix Invasion p.81'),
('xiticix-resin-spike-gun', 'Xiticix Resin Spike Gun', 'rifts', 'weapon', 20, 90000, 'Printed as "90,000-120,00 credits", the upper figure short a digit; read as 90,000-120,000. Considered a Techno-Wizard weapon; very rare.', '1D6 M.D. per three-spike burst, or 2 M.D. per single shot; bayonet 1D4 M.D.', 1, '400 ft', '60 spikes (20 bursts); 24 P.P.E. or 48 I.S.P. to recreate them', 'Each three-spike burst is one melee attack; one roll to strike, and the whole burst hits or misses', NULL, NULL, NULL, 'A sub-machinegun or small assault rifle that fires resin spikes, used only by Warriors, with a bayonet as standard. Defenders dodge at -6. Reloaded by the shooter or a Queen; only a Queen can make one.', 'Rifts World Book 23: Xiticix Invasion p.81-82'),
('xiticix-shooting-shoulder-spikes', 'Xiticix Shooting Shoulder Spikes', 'rifts', 'weapon', 10, NULL, 'Available only to Xiticix.', '1 M.D. per spike; +1D6 M.D. to shoulder blocks and ram attacks', 1, '60 ft', '12 spikes; 12 P.P.E. or 24 I.S.P. to recreate them', 'One spike or a volley of 2, 4 or 6, each one melee attack; one roll to strike, and the whole volley hits or misses', NULL, NULL, 15, 'Shoulder spikes that launch, in effect a Techno-Wizard weapon, made only by a Queen. Adds 15 M.D.C. to the arm, and must be destroyed before the upper arm can be severed. No bonuses to strike apply; defenders dodge at -3. Reloaded by the user or a Queen. Weighs 10-12 lbs.', 'Rifts World Book 23: Xiticix Invasion p.81'),
('xiticix-resin-spitter', 'Xiticix Resin Spitter', 'rifts', 'weapon', 40, 130000, '130,000-160,000 credits; considered a Techno-Wizard weapon and very rare.', 'None; each glob impairs and restrains (see the Xiticix Digger''s resin glob attack). Bayonet 1D4 M.D.', 1, '240 ft', '8 globs; 30 P.P.E. or 60 I.S.P. to recharge', 'Twice per melee round, each one melee attack', NULL, NULL, NULL, 'Also called the Resin Gun or Glop Rifle. Fires globs of quick-drying building resin, each about three feet across: one covers half of a human-sized target, two restrain it completely, and larger creatures need more. The resin hardens in 1D4+1 melee rounds. Two hands for most humanoids, otherwise -4 to strike; Supernatural P.S. or a bionic or robot P.S. of 30 fires it one-handed. Bayonet as standard. Only a Queen can make one.', 'Rifts World Book 23: Xiticix Invasion p.82'),
('xiticix-tk-rifle', 'Xiticix TK-Rifle', 'rifts', 'weapon', 20, 110000, '110,000-150,000 credits; considered a Techno-Wizard weapon and rare.', '4D6 M.D. per blast; bayonet 1D4 M.D.', 1, '4,000 ft', '40 blasts; 20 P.P.E. or 40 I.S.P. to recharge', 'Printed with the Resin Spike Gun''s wording: each three-spike burst is one melee attack, one roll to strike', NULL, NULL, NULL, 'The Xiticix telekinetic rifle, working much like Techno-Wizardry and the TK-Machinegun, with a bayonet as standard that Warriors may coat with their poison. Defenders dodge at -6. Recharged by the shooter or a Queen; only a Queen can make one.', 'Rifts World Book 23: Xiticix Invasion p.82');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 15 Xiticix Invasion gear rows are in' AS assertion, count(*) AS got, 15 AS want
  FROM gear WHERE slug IN ('xiticix-bayonet', 'xiticix-double-dagger', 'xiticix-hooked-short-sword', 'xiticix-mace', 'xiticix-long-sword', 'xiticix-spear', 'xiticix-spike-whip', 'xiticix-beheading-axe', 'xiticix-sickle-axe', 'xiticix-resin-claws', 'xiticix-resin-shoulder-spikes', 'xiticix-resin-spike-gun', 'xiticix-shooting-shoulder-spikes', 'xiticix-resin-spitter', 'xiticix-tk-rifle');
SELECT 'and every one cites Xiticix Invasion' AS assertion, count(*) AS got, 15 AS want
  FROM gear WHERE slug IN ('xiticix-bayonet', 'xiticix-double-dagger', 'xiticix-hooked-short-sword', 'xiticix-mace', 'xiticix-long-sword', 'xiticix-spear', 'xiticix-spike-whip', 'xiticix-beheading-axe', 'xiticix-sickle-axe', 'xiticix-resin-claws', 'xiticix-resin-shoulder-spikes', 'xiticix-resin-spike-gun', 'xiticix-shooting-shoulder-spikes', 'xiticix-resin-spitter', 'xiticix-tk-rifle') AND source_book LIKE 'Rifts World Book 23: Xiticix Invasion p.%';

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('add-xiticix-invasion-gear.sql');
